    do local i,_d_i=(1),(1) for _=1,360 do
        Render4V("white",self.x+self.r*cos(i+1),self.y+self.r*sin(i+1),0.5
                        ,self.x+(self.r+self.d)*cos(i+1),self.y+(self.r+self.d)*sin(i+1),0.5
                        ,self.x+(self.r+self.d)*cos(i),self.y+(self.r+self.d)*sin(i),0.5
