    lasttask=task.New(self,function()
        last=New(_editor_class["T_Terrence_Circle"],self.x,self.y,self.x,self.y,0,2,col)
        _connect(self,last,0,true)
        local edge=last;
        self.r=0;
        self.rot=ran:Float(0,360);
        local dr=10;
        for _=1,_infinite do
            do
                local _beg_r=0 local r=_beg_r local _end_r=300 local _w_r=0 local _d_w_r=1/(600-1)
                for _=1,600 do
                    if IsValid(edge) then
                        edge.x,edge.y,edge.r=self.x,self.y,r;
                        self.r=r;
                        self.rot=self.rot+rot_v;
                    else
                    end
                    task._Wait(1)
                    _w_r=_w_r+_d_w_r r=(_beg_r-_end_r)*(_w_r-1)^2+_end_r
                end
            end
            do
                local _beg_r=300 local r=_beg_r local _end_r=0 local _w_r=0  local _d_w_r=1/(600-1)
                for _=1,600 do
                    if IsValid(edge) then
                        edge.x,edge.y,edge.r=self.x,self.y,r;
                        self.r=r;
                        self.rot=self.rot+rot_v;
                    else
                    end
                    task._Wait(1)
                    _w_r=_w_r+_d_w_r r=(_end_r-_beg_r)*_w_r^2+_beg_r
                end
            end
        end
    end)
    lasttask=task.New(self,function()
        local bullets={};
        do local i,_d_i=(1),(1) for _=1,24 do
            last=New(_editor_class["T_Terrence_spell"],self.x,self.y,scol)
            _connect(self,last,0,true)
            bullets[i]=last;
        i=i+_d_i end end
        for _=1,_infinite do
            do
                local _beg_i=1 local i=_beg_i local _end_i=24 local _d_i=(_end_i-_beg_i)/(24-1)
                for _=1,24 do
                    if IsValid(bullets[i]) then
                        local ang=360/24*i+self.rot;
                        bullets[i].x=self.x+self.r*cos(ang);
                        bullets[i].y=self.y+self.r*sin(ang);
                    else
                    end
                    i=i+_d_i
                end
            end
            task._Wait(1)
        end
    end)
    lasttask=task.New(self,function()
        for _=1,_infinite do
            if self.x-self.r>192 or self.x+self.r<-192 or self.y+self.r<-224 or self.y-self.r>224 then
                _del(self,false)
            else
            end
            task._Wait(1)
        end
    end)
end
